begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values ('fc110000-0000-0000-0000-000000000001','customer-test@example.test','{}');
create temporary table customer_ids(label text primary key,id uuid default gen_random_uuid());
insert into customer_ids(label) values ('empty'),('contact'),('quote'),('pi'),('order'),('inquiry'),('task'),('outbound'),('race'),('batch-a'),('batch-c'),('rollback');
insert into romiku_formal_customers(id,name) select id,'QA-'||label from customer_ids;
insert into romiku_customer_contacts(formal_customer_id,name) select id,'QA contact' from customer_ids where label in ('contact','rollback');
insert into romiku_quotes(formal_customer_id,counterparty_snapshot) select id,'{"name":"historic buyer"}' from customer_ids where label='quote';
insert into romiku_pis(formal_customer_id,counterparty_snapshot) select id,'{"name":"historic PI"}' from customer_ids where label='pi';
insert into romiku_orders(formal_customer_id,counterparty_snapshot,status,archived_at) select id,'{"name":"historic order"}','cancelled',now() from customer_ids where label='order';
insert into romiku_website_inquiries(formal_customer_id,customer_name) select id,'QA inquiry' from customer_ids where label='inquiry';
insert into romiku_manual_tasks(formal_customer_id,title,completed_at) select id,'QA task',now() from customer_ids where label='task';
insert into romiku_outbound_companies(name) values ('QA customer origin');
update romiku_formal_customers set source_outbound_company_id=(select id from romiku_outbound_companies where name='QA customer origin') where id=(select id from customer_ids where label='outbound');
insert into romiku_production_orders(order_id,status) select id,'cancelled' from romiku_orders where formal_customer_id=(select id from customer_ids where label='order');
insert into romiku_packing_lists(order_id) select id from romiku_orders where formal_customer_id=(select id from customer_ids where label='order');
insert into romiku_payments(order_id,kind,amount) select id,'deposit',1 from romiku_orders where formal_customer_id=(select id from customer_ids where label='order');
grant select on customer_ids to authenticated;
select ok(has_table_privilege('authenticated','romiku_formal_customers','SELECT,INSERT,UPDATE'),'existing non-delete privileges preserved');
select ok(not has_table_privilege('authenticated','romiku_formal_customers','DELETE'),'direct DELETE grant revoked');
set local role anon;
select throws_ok($$select public.romiku_delete_record('formal_customer',gen_random_uuid())$$,'42501',null,'anon RPC denied');
select throws_ok($$delete from public.romiku_formal_customers where false$$,'42501',null,'anon table delete denied');
reset role;
set local role authenticated;
select throws_ok($$delete from romiku_formal_customers where false$$,'42501',null,'authenticated direct DELETE denied');
select is(romiku_delete_record('formal_customer',gen_random_uuid())->>'code','UNAUTHENTICATED','no auth uid denied');
select set_config('request.jwt.claim.sub','fc110000-0000-0000-0000-000000000001',true);
select is(romiku_delete_record('formal_customer',gen_random_uuid())->>'code','NOT_FOUND','missing customer');
select is(jsonb_array_length(romiku_delete_preflight('formal_customer',array[(select id from customer_ids where label='empty')])->'deletable'),1,'empty preflight eligible');
select is(romiku_delete_record('formal_customer',(select id from customer_ids where label='empty'))->>'ok','true','empty customer deleted');
select is(romiku_delete_record('formal_customer',(select id from customer_ids where label='contact'))->>'ok','true','contacts-only customer deleted');
select is((select count(*) from romiku_customer_contacts where formal_customer_id=(select id from customer_ids where label='contact')),0::bigint,'owned contacts deleted');
select is(romiku_delete_record('formal_customer',id)->>'code','HAS_DOWNSTREAM',label || ' blocks deletion') from customer_ids where label in ('quote','pi','order','inquiry','task','outbound');
select is((romiku_customer_dependencies((select id from customer_ids where label='order'))->>'production')::int,1,'cancelled Production counted through Order');
select is((romiku_customer_dependencies((select id from customer_ids where label='order'))->>'packing')::int,1,'Packing counted through Order');
select is((romiku_customer_dependencies((select id from customer_ids where label='order'))->>'payments')::int,1,'Payment counted through Order');
select is(jsonb_array_length(romiku_delete_preflight('formal_customer',array_agg(id))->'blocked'),6,'all dependency types blocked in preflight') from customer_ids where label in ('quote','pi','order','inquiry','task','outbound');
select is(jsonb_array_length(romiku_delete_preflight('formal_customer',array[(select id from customer_ids where label='race')])->'deletable'),1,'race initially eligible');
insert into romiku_quotes(formal_customer_id) select id from customer_ids where label='race';
select is(romiku_delete_record('formal_customer',(select id from customer_ids where label='race'))->>'code','HAS_DOWNSTREAM','new reference after preflight blocks execution');
select is(jsonb_array_length(romiku_delete_preflight('formal_customer',array_agg(id))->'deletable'),2,'mixed batch has two eligible') from customer_ids where label in ('batch-a','order','batch-c');
select is(jsonb_array_length(romiku_batch_delete('formal_customer',array_agg(id))->'succeeded'),2,'mixed batch deletes only eligible two') from customer_ids where label in ('batch-a','order','batch-c');
select is((select count(*) from romiku_formal_customers where id=(select id from customer_ids where label='order')),1::bigint,'blocked batch customer retained');
select is(romiku_batch_status('formal_customer',array[(select id from customer_ids where label='order')],'arbitrary')->>'code','INVALID_STATUS','fixed status whitelist');
select is(jsonb_array_length(romiku_batch_status('formal_customer',array_agg(id),'inactive')->'succeeded'),3,'batch disable succeeds') from customer_ids where label in ('quote','pi','order');
select is((select count(*) from romiku_formal_customer_directory where id in (select id from customer_ids where label in ('quote','pi','order')) and status='inactive'),3::bigint,'inactive directory retained with status');
select is((romiku_customer_documents((select id from customer_ids where label='order'))->>'total_count')::int,3,'inactive Customer 360 retains Order, Production and Packing');
select is((select counterparty_snapshot from romiku_orders where formal_customer_id=(select id from customer_ids where label='order')),'{"name":"historic order"}'::jsonb,'Order snapshot unchanged');
select is((select counterparty_snapshot from romiku_quotes where formal_customer_id=(select id from customer_ids where label='quote')),'{"name":"historic buyer"}'::jsonb,'Quote snapshot unchanged');
select is((select counterparty_snapshot from romiku_pis where formal_customer_id=(select id from customer_ids where label='pi')),'{"name":"historic PI"}'::jsonb,'PI snapshot unchanged');
select is((romiku_customer_business_history((select id from customer_ids where label='order'))->>'total_count')::int,1,'inactive business history retains Order');
select is(jsonb_array_length(romiku_batch_status('formal_customer',array_agg(id),'active')->'succeeded'),3,'re-enable succeeds') from customer_ids where label in ('quote','pi','order');
reset role;
create function pg_temp.fail_customer_delete() returns trigger language plpgsql as $$begin raise exception 'injected failure'; end$$;
create trigger qa_customer_fail before delete on romiku_formal_customers for each row when (old.name='QA-rollback') execute function pg_temp.fail_customer_delete();
set local role authenticated;
select is(romiku_delete_record('formal_customer',(select id from customer_ids where label='rollback'))->>'code','DELETE_FAILED','safe error on deletion failure');
select is((select count(*) from romiku_customer_contacts where formal_customer_id=(select id from customer_ids where label='rollback')),1::bigint,'child deletion rolled back');
select is((select count(*) from romiku_formal_customers where id=(select id from customer_ids where label='rollback')),1::bigint,'parent retained on failure');
select * from finish();
rollback;
